        # Look at surrounding bytes
        start = max(0, i-2)
        end = min(len(data), i+4)
        non_ascii.append((i, data[start:end]))

print(f'Total non-ASCII occurrences: {len(non_ascii)}')
print()

# Group by the multi-byte sequence
sequences = {}
for pos, snippet in non_ascii:
    seq = data[pos]
    key = seq
    sequences[key] = sequences.get(key, 0) + 1

print('Unique non-ASCII byte values:')
for byte_val, count in sorted(sequences.items()):
    print(f'  0x{byte_val:02x}: {count} occurrences')
